// Do not edit by hand — run `npm run wellbeing`. The build fails if this file and the source
// disagree, so an edit here is lost rather than merely wrong.
//
// Live well. Five habits in a person's own words, ten refusals, and no number anywhere: no score,
// no grade, no target, no streak, no rank, no percentage and no unit. Three of the refusals below
// say those words out loud, because the absence is the feature and a reader cannot see an absence.
// A Live well SCREEN may not — scripts/check-boundaries.mjs fails on any of them in a screen, and
// skips this file because a generated carrier is the contract in another language.
//
// Nothing here is measured. No device is read, no permission is asked for, and nothing a person
// writes is stored anywhere or sent to anybody. Fictional entries.

import Foundation

enum WellbeingData {
    /// One thing a person might write about. `prompt` is a question and never an instruction, and
    /// there is no unit, no range and no field for a number — see the generator.
    struct Habit: Identifiable, Hashable { let id: String; let name: String; let prompt: String }
    /// Something Live well will not do, in the words a person reads. The reasoning stays in the
    /// contract: it is written for whoever is about to delete the sentence, not for the patient.
    struct Refusal: Identifiable, Hashable { let id: String; let sentence: String }
    /// A fictional entry, dated in days from today so the preview never goes stale.
    struct SampleEntry: Hashable { let habit: String; let dayOffset: Int; let text: String }

    // A patient who writes 'walked to the shops and back, easier than last week' has recorded
    // something a doctor can use. A product that turned that into a score has replaced it with
    // something nobody can use.
    static let statement = "A place to write down what you did, in your own words, and see it beside the visits and readings already on your record."
    static let isNot = "It is not a diagnosis, a treatment, a plan, or an opinion about your health. Nothing here is reviewed by a clinician unless you take it to one."

    // Five, all unitless, all in the person's own words. There is no field anywhere in this feature
    // that takes a number, which is the single decision that makes the rest of it safe.
    static let habits: [Habit] = [
        .init(id: "moving", name: "Moving",
              prompt: "What did you do, and how did it feel?"),
        .init(id: "eating", name: "Eating",
              prompt: "What did you eat today that you want to remember?"),
        .init(id: "sleeping", name: "Sleeping",
              prompt: "How did you sleep, and how do you feel this morning?"),
        .init(id: "feeling", name: "How you are",
              prompt: "In a word or two, how are you today?"),
        .init(id: "medicines", name: "Taking your medicines",
              prompt: "Did you take them today?")
    ]
    static func habit(_ id: String) -> Habit? { habits.first { $0.id == id } }

    // No screen in this feature may show a score, a grade, a target, a streak, a rank, a percentage,
    // a unit, or a sentence that praises or corrects the person reading it.
    // scripts/check-boundaries.mjs fails the build on each of those, and the check exists because
    // every one of them is a normal, well-intentioned product decision that would be wrong here.
    static let refusals: [Refusal] = [
        .init(id: "no-diagnosis",
              sentence: "Nothing here is a diagnosis or a clinical opinion. What you write down is yours, and a nurse or a doctor is the one who decides what it means."),
        .init(id: "no-target",
              sentence: "MyThuso does not set you a target. If you want one, it is yours to choose and yours to change."),
        .init(id: "no-weight-score",
              sentence: "There is no score, no grade and no weight goal in MyThuso."),
        .init(id: "no-medicine-advice",
              sentence: "MyThuso never tells you to start, stop or change a medicine. Ask the doctor who prescribed it."),
        .init(id: "no-reading-interpreted",
              sentence: "A reading on your Health Passport is explained there, by the contract a clinician agreed. Nothing you write here changes what a reading means."),
        .init(id: "no-comparison",
              sentence: "You are not compared with anybody else, and nobody else sees this unless you share it."),
        .init(id: "no-punished-gap",
              sentence: "A day you did not write anything is just a day. Nothing is lost and nothing resets."),
        .init(id: "no-device",
              sentence: "Nothing here is measured. No watch, band or phone sensor is connected, and none is read."),
        .init(id: "no-sharing-by-default",
              sentence: "What you write here is not added to your record and is not sent to your nurse or doctor. You can take it to them; MyThuso does not."),
        .init(id: "no-cheerfulness-about-illness",
              sentence: "MyThuso does not congratulate you and does not tell you how you are doing.")
    ]
    static func refusal(_ id: String) -> Refusal? { refusals.first { $0.id == id } }

    // Five fictional entries so the timeline shows what it is for rather than an empty box on the
    // day somebody looks at it. Day offsets from today, like every other fixture in this catalogue,
    // so the preview never goes stale — and deliberately not one per day: there is a gap at
    // yesterday-but-one and another before the oldest, because a record with no gaps in it is the
    // chart this feature refuses to draw. Nothing here is anybody's, and nothing a person writes in
    // the preview outlives the app being closed.
    static let sampleEntries: [SampleEntry] = [
        .init(habit: "moving", dayOffset: 0, text: "Walked to the shops and back. Easier than last week."),
        .init(habit: "medicines", dayOffset: 0, text: "Yes, both of them, with breakfast."),
        .init(habit: "sleeping", dayOffset: -1, text: "Woke at three and could not get back off. Slow morning."),
        .init(habit: "eating", dayOffset: -2, text: "Pap and beans. I remembered the spinach this time."),
        .init(habit: "feeling", dayOffset: -4, text: "Tired, but all right.")
    ]

    // It is a record rather than a chart. A chart of a body's week invites a line of best fit
    // through somebody's life.
    static let timeline = "What you wrote, when you wrote it, newest first, beside the visits and readings already on your record."

    // The useful thing a diary does is get read out loud in a room with a nurse in it. That is the
    // whole feature: not an integration, a prompt to bring it.
    static let bringIt = "Bring this to your next visit."
    static let bringItHowItWorks = "It opens the visit's own screen with what you wrote alongside it. Nothing is copied into the record until a clinician records it as part of the visit."

    /// It names clinical-records rather than a capability of its own, because the honest thing to disclose is that nothing here is held anywhere real. There is no wellbeing supplier to be blocked on and inventing one would be inventing a gap.
    static let capability = "clinical-records"
}
